# ── International tickers ─────────────────────────────────────────────
# Loaded from disk: Japan (.T), Europe (.L/.DE/.PA), Canada (.TO), Australia (.AX),
# Hong Kong (.HK), South Korea (.KS), Taiwan (.TWO), Singapore (.SI),
# Mexico (.BA/.MX), Brazil (.SA), Turkey (.IS)
import os

_intl_path = os.path.join(os.path.dirname(__file__), 'intl_tickers.txt')
if os.path.exists(_intl_path):
    with open(_intl_path) as _f:
        INTERNATIONAL_TICKERS = sorted(set(
            line.strip() for line in _f if line.strip()
        ))
else:
    INTERNATIONAL_TICKERS = []
del os, _f, _intl_path  # clean up namespace

# ── Regions mapping ─────────────────────────────────────────────────
REGIONS = {
    'usa': USA_TICKERS,
    'sweden': SWEDEN_TICKERS,
    'china': CHINA_TICKERS,
    'india': INDIA_TICKERS,
    'international': INTERNATIONAL_TICKERS,
}

REGION_LABELS = {
    'usa': 'United States',
    'sweden': 'Sweden',
    'china': 'China',
    'india': 'India',
    'international': 'International (HK/JP/KR/TW/SA/TR/MX/BR/AU/UK/DE/FR)',
}


def get_region_count():
    """Return dict of region -> count of tickers."""
    return {region: len(tickers) for region, tickers in REGIONS.items()}


def get_total_count():
    """Return total number of unique tickers across all regions."""
    all_tickers = set()
    for tickers in REGIONS.values():
        all_tickers.update(tickers)
    return len(all_tickers)


def get_universe(region=None):
    """Get tickers for a specific region, or all regions if None."""
    if region:
        return REGIONS.get(region, [])
    all_tickers = set()
    for tickers in REGIONS.values():
        all_tickers.update(tickers)
    return sorted(all_tickers)

def get_all_universes():
    """Return all tickers across all regions."""
    return get_universe(None)
